/*!
 * Simplified Markdown parser for offline rendering.
 * This is NOT the official marked.js build but provides
 * enough functionality (headings, paragraphs, lists, emphasis, code)
 * for the presentation outline.
 * Released under the MIT License.
 */
(function () {
  function escapeHtml(str) {
    return str
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function renderInline(text) {
    return text
      .replace(/`([^`]+)`/g, "<code>$1</code>")
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/\*([^*]+)\*/g, "<em>$1</em>")
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
  }

  function parseMarkdown(md) {
    const lines = md.replace(/\r\n?/g, "\n").split("\n");
    const html = [];
    let inList = false;

    function closeList() {
      if (inList) {
        html.push("</ul>");
        inList = false;
      }
    }

    for (const rawLine of lines) {
      const line = rawLine.trimEnd();
      if (!line.trim()) {
        closeList();
        html.push("");
        continue;
      }

      const heading = line.match(/^(#{1,6})\s+(.*)$/);
      if (heading) {
        closeList();
        const level = heading[1].length;
        html.push(
          `<h${level}>${renderInline(escapeHtml(heading[2]))}</h${level}>`
        );
        continue;
      }

      const bullet = line.match(/^[-*]\s+(.*)$/);
      if (bullet) {
        if (!inList) {
          html.push("<ul>");
          inList = true;
        }
        html.push(`<li>${renderInline(escapeHtml(bullet[1]))}</li>`);
        continue;
      }

      closeList();
      html.push(`<p>${renderInline(escapeHtml(line))}</p>`);
    }

    closeList();
    return html.join("\n").replace(/\n{2,}/g, "\n");
  }

  window.marked = {
    parse: parseMarkdown,
  };
})();
